def parsear_duracion(s):
    minutos = 0
    for token in s.split():
        valor, unidad = token[:-1], token[-1]
        if unidad == 'h':
            minutos += int(valor) * 60
        elif unidad == 'm':
            minutos += int(valor)
    return minutos

def es_palindromo(s):
    limpia = ''.join(c.lower() for c in s if c.isalnum())
    return limpia == limpia[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    inicio = 0
    fin = len(lista) - 1
    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inicio = medio + 1
        else:
            fin = medio - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        resultado.setdefault(valor, []).append(item)
    return resultado

