def a_romano(n):
    val = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]
    resultado = ''
    for valor, simbolo in val:
        while n >= valor:
            resultado += simbolo
            n -= valor
    return resultado

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    anterior = 0
    for char in reversed(s):
        valor = valores[char]
        if valor < anterior:
            resultado -= valor
        else:
            resultado += valor
            anterior = valor
    return resultado

def mayor_racha(lista):
    if not lista:
        return None
    mejor_elem, mejor_long = lista[0], 1
    elem, long = lista[0], 1
    for i in range(1, len(lista)):
        if lista[i] == elem:
            long += 1
        else:
            elem, long = lista[i], 1
        if long > mejor_long:
            mejor_elem, mejor_long = elem, long
    return (mejor_elem, mejor_long)

def a_snake(s):
    s = s.replace('_', ' ')
    s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s)
    s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
    return s.lower()

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for num in range(2, n + 1):
        es_primo = True
        for divisor in range(2, num):
            if num % divisor == 0:
                es_primo = False
                break
        if es_primo:
            primos_list.append(num)
    return primos_list

