def contar_islas(grid):
    if not grid:
        return 0

    filas = len(grid)
    columnas = len(grid[0])
    islas = 0

    def visitar(i, j):
        if 0 <= i < filas and 0 <= j < columnas and grid[i][j] == 1:
            grid[i][j] = 0
            visitar(i - 1, j)
            visitar(i + 1, j)
            visitar(i, j - 1)
            visitar(i, j + 1)

    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1:
                islas += 1
                visitar(i, j)

    return islas

def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # borrado
                dp[i][j - 1] + 1,      # inserción
                dp[i - 1][j - 1] + cost  # sustitución/acuerdo
            )
    return dp[m][n]

def validar_password(p):
    return (
        len(p) >= 8
        and any(c.isupper() for c in p)
        and any(c.islower() for c in p)
        and any(c.isdigit() for c in p)
        and any(not c.isalnum() for c in p)
    )

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

