def sumar_romanos(a, b):
    simbolos = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    inverso = {v: k for k, v in simbolos.items()}

    def romano_a_entero(s):
        s = s.upper()
        total = 0
        anterior = 0
        for char in reversed(s):
            valor = simbolos[char]
            if valor < anterior:
                total -= valor
            else:
                total += valor
                anterior = valor
        return total

    def entero_a_romano(n):
        valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
        simbolos_ = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']
        resultado = ''
        for valor, simbolo in zip(valores, simbolos_):
            while n >= valor:
                n -= valor
                resultado += simbolo
        return resultado

    return entero_a_romano(romano_a_entero(a) + romano_a_entero(b))

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    valor = d
    for parte in partes:
        if isinstance(valor, dict) and parte in valor:
            valor = valor[parte]
        else:
            return defecto
    return valor

